using AcxiomCRM.Data;using AcxiomCRM.Models;using AcxiomCRM.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Controllers.Api;
[ApiController,Route("api/opportunities"),Authorize] public class OpportunitiesApiController(ApplicationDbContext db,IAuditService audit):ControllerBase {
 [HttpGet]public async Task<IActionResult>Get(){var q=db.Opportunities.AsQueryable();if(!User.IsInRole("Admin")&&!User.IsInRole("Manager"))q=q.Where(x=>x.AssignedTo==User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)!.Value);return Ok(await q.Select(x=>new{x.OpportunityId,x.OpportunityName,x.Amount,x.Probability,x.Stage,x.ExpectedCloseDate,x.Status,WeightedValue=x.Amount*x.Probability/100m}).ToListAsync());}
 [HttpPost]public async Task<IActionResult>Create(Opportunity input){if(!ModelState.IsValid)return ValidationProblem(ModelState);if(input.Amount<=0)return BadRequest(new{message="Opportunity Amount must be greater than 0."});if(input.Probability is <0 or >100)return BadRequest(new{message="Probability must be between 0 and 100."});if(input.Status=="Open"&&input.ExpectedCloseDate.Date<DateTime.Today)return BadRequest(new{message="Expected Close Date cannot be in the past."});input.OpportunityId=0;input.AssignedTo=User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value;db.Add(input);await db.SaveChangesAsync();await audit.WriteAsync("Create","Opportunity",input.OpportunityId.ToString());return Created($"/api/opportunities/{input.OpportunityId}",new{input.OpportunityId,input.OpportunityName,input.Amount,input.Stage});}
}
